let lang='zh',filter='all',csrIndex=0,openedService=null;
const $=s=>document.querySelector(s);
const pick=a=>a[lang==='zh'?0:1];
function renderServices(){ $('#service-grid').innerHTML=services.map((s,i)=>`<button class="service-card" data-service="${i}" ${filter!=='all'&&filter!==s.category?'hidden':''} aria-label="${lang==='zh'?'了解':'Explore'} ${lang==='zh'?s.zh:s.en}"><div class="service-image"><img src="assets/${s.image}" alt="${s.en}" loading="lazy"><span class="service-num">0${i+1}</span><span class="round-arrow" aria-hidden="true">↗</span></div><div class="service-meta"><div><h3>${lang==='zh'?s.zh:s.en}</h3><p class="en-label">${lang==='zh'?s.en.toUpperCase():'RS TECHNOLOGIES'}</p>${i===4?`<p class="service-summary">${pick(s.desc)}</p>`:''}</div><span>${pick(s.tag)}</span></div></button>`).join(''); }
function renderCSR(){document.querySelectorAll('[data-csr]').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===csrIndex));b.tabIndex=i===csrIndex?0:-1});$('#csr-panel').setAttribute('aria-labelledby','csr-tab-'+csrIndex);if(csrIndex===2){$('#csr-panel').innerHTML=`<p class="gallery-caption">${lang==='zh'?'來自原站的活動影像，記錄團隊與社群的連接。':'Moments from our original website, connecting our team and community.'}</p><div class="gallery"><img src="assets/bf925f121df4ea08.webp" alt="${lang==='zh'?'活動精華 1':'Activity highlight 1'}" loading="lazy"><img src="assets/a445ed6777757164.webp" alt="${lang==='zh'?'活動精華 2':'Activity highlight 2'}" loading="lazy"><img src="assets/f4a78e6ffc8e7200.webp" alt="${lang==='zh'?'活動精華 3':'Activity highlight 3'}" loading="lazy"></div>`;return}const c=csr[csrIndex];$('#csr-panel').innerHTML=`<img src="assets/${c.image}" alt="${pick(c.alt)}" loading="lazy"><div class="csr-content"><p class="eyebrow">${c.label}</p><h3>${pick(c.title)}</h3><p>${pick(c.desc)}</p><ul>${pick(c.items).map(t=>`<li>${t}</li>`).join('')}</ul></div>`;}
function renderDialog(i){const s=services[i];$('#dialog-content').innerHTML=`<img class="dialog-img" src="assets/${s.image}" alt="${s.en}"><div class="dialog-body"><p class="eyebrow">0${i+1} / ${s.en.toUpperCase()}</p><h2 id="dialog-title">${lang==='zh'?s.zh:s.en}</h2><p>${pick(s.desc)}</p><div class="dialog-tags">${pick(s.tags).map(t=>`<span>${t}</span>`).join('')}</div><a href="#quote" class="button bright" data-quote="${i}"><span>${lang==='zh'?'洽談此項服務':'Discuss this solution'}</span><span>↗</span></a></div>`;$('#service-dialog').setAttribute('aria-labelledby','dialog-title');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-service]');if(b){openedService=Number(b.dataset.service);renderDialog(openedService);$('#service-dialog').showModal();return}const q=e.target.closest('[data-quote]');if(q){$('#quote-service').selectedIndex=Number(q.dataset.quote)+1;$('#service-dialog').close();openedService=null}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===f);b.setAttribute('aria-pressed',String(b===f))});renderServices()}const c=e.target.closest('[data-csr]');if(c){csrIndex=Number(c.dataset.csr);renderCSR()}if(e.target.closest('nav a')){$('nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}});
$('.dialog-close').addEventListener('click',()=>{$('#service-dialog').close();openedService=null});$('#service-dialog').addEventListener('click',e=>{if(e.target===$('#service-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){e.target.close();openedService=null}}});$('#service-dialog').addEventListener('close',()=>{openedService=null});
$('#menu').addEventListener('click',()=>{const open=$('nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));$('#menu').setAttribute('aria-label',lang==='zh'?(open?'關閉導覽':'開啟導覽'):(open?'Close navigation':'Open navigation'))});
$('#language').addEventListener('click',()=>{lang=lang==='zh'?'en':'zh';document.documentElement.lang=lang==='zh'?'zh-Hant':'en';document.body.classList.toggle('en',lang==='en');document.querySelectorAll('[data-zh][data-en]').forEach(el=>{el.textContent=el.dataset[lang]});$('#language').innerHTML=lang==='zh'?'EN <span>↗</span>':'繁中 <span>↗</span>';$('#language').setAttribute('aria-label',lang==='zh'?'Switch to English':'切換繁體中文');$('.dialog-close').setAttribute('aria-label',lang==='zh'?'關閉':'Close');document.title=lang==='zh'?'RS Technologies｜讓科技，成就下一步':'RS Technologies | Technology, moving you forward';renderServices();renderCSR();if(openedService!==null)renderDialog(openedService);$('#form-status').textContent='';});
$('.csr-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();csrIndex=e.key==='Home'?0:e.key==='End'?2:(csrIndex+(e.key==='ArrowRight'?1:2))%3;renderCSR();$('#csr-tab-'+csrIndex).focus()});
// Contact submissions are handled by cms.js.
$('#year').textContent=new Date().getFullYear();renderServices();renderCSR();

// Reference-inspired navigation, contact rail, scroll motion and image viewing.
const mega=$('.nav-solutions');
$('#mega-toggle').addEventListener('click',()=>{const expanded=mega.classList.toggle('expanded');$('#mega-toggle').setAttribute('aria-expanded',String(expanded));});
document.addEventListener('click',e=>{if(!e.target.closest('.nav-solutions')||e.target.closest('[data-service]')||e.target.closest('.mega-menu a')){mega.classList.remove('expanded');$('#mega-toggle').setAttribute('aria-expanded','false');if(document.activeElement?.closest('.mega-menu'))document.activeElement.blur();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){mega.classList.remove('expanded');$('#mega-toggle').setAttribute('aria-expanded','false');if(document.activeElement?.closest('.mega-menu'))$('#mega-toggle').focus();}});
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduceMotion&&'IntersectionObserver' in window){const revealObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target);}})},{threshold:.08});document.querySelectorAll('.about-grid,.certs,.section-heading,.hap-copy,.partner-heading,.logo-grid').forEach(el=>{el.classList.add('reveal');revealObserver.observe(el);});}
function updateProgress(){const total=document.documentElement.scrollHeight-innerHeight;$('.reading-progress').style.width=(total>0?scrollY/total*100:0)+'%';document.querySelector('.header').classList.toggle('scrolled',scrollY>50);}
addEventListener('scroll',updateProgress,{passive:true});addEventListener('resize',updateProgress);updateProgress();
const sectionObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('is-current',a.hash==='#'+entry.target.id));}})},{rootMargin:'-15% 0px -65% 0px'});document.querySelectorAll('main>section[id]').forEach(el=>sectionObserver.observe(el));
const galleryImages=['bf925f121df4ea08.webp','a445ed6777757164.webp','f4a78e6ffc8e7200.webp'];let galleryIndex=0;
function showGallery(index){galleryIndex=(index+galleryImages.length)%galleryImages.length;$('#gallery-large').src='assets/'+galleryImages[galleryIndex];$('#gallery-large').alt=(lang==='zh'?'活動精華 ':'Activity highlight ')+(galleryIndex+1);$('#gallery-count').textContent=String(galleryIndex+1).padStart(2,'0')+' / 03';}
const originalRenderCSR=renderCSR;
renderCSR=function(){originalRenderCSR();document.querySelectorAll('.gallery img').forEach((img,i)=>{const button=document.createElement('button');button.type='button';button.dataset.gallery=String(i);button.setAttribute('aria-label',(lang==='zh'?'放大活動圖片 ':'Enlarge activity image ')+(i+1));img.replaceWith(button);button.append(img);});};
document.addEventListener('click',e=>{const imgButton=e.target.closest('[data-gallery]');if(imgButton){showGallery(Number(imgButton.dataset.gallery));$('#gallery-dialog').showModal();}});
$('.gallery-close').addEventListener('click',()=>$('#gallery-dialog').close());$('.gallery-prev').addEventListener('click',()=>showGallery(galleryIndex-1));$('.gallery-next').addEventListener('click',()=>showGallery(galleryIndex+1));$('#gallery-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();showGallery(galleryIndex-1)}if(e.key==='ArrowRight'){e.preventDefault();showGallery(galleryIndex+1)}});
$('#language').addEventListener('click',()=>{$('#mega-toggle').setAttribute('aria-label',lang==='zh'?'展開服務選單':'Expand solutions menu');$('#gallery-dialog').setAttribute('aria-label',lang==='zh'?'活動圖片':'Activity photos');$('.gallery-close').setAttribute('aria-label',lang==='zh'?'關閉圖片':'Close image');$('.gallery-prev').setAttribute('aria-label',lang==='zh'?'上一張':'Previous image');$('.gallery-next').setAttribute('aria-label',lang==='zh'?'下一張':'Next image');});
renderCSR();
$('.rail-primary').setAttribute('aria-label','洽談項目');
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{$('#menu').setAttribute('aria-label',lang==='zh'?'開啟導覽':'Open navigation');}));
$('#language').addEventListener('click',()=>{$('.rail-primary').setAttribute('aria-label',lang==='zh'?'洽談項目':'Enquire about a project');});
